documents.eventide/acceptance_output.py:
"""Bounded, redacted text artifacts for independent acceptance only."""

from __future__ import annotations

import codecs
import errno
import hashlib
import os
import re
import stat
import time
import uuid
from collections import defaultdict
from collections.abc import Callable
from dataclasses import dataclass
from pathlib import Path
from typing import Any, BinaryIO

from eventide.previews import SafeTextBuffer
from eventide.store import RuntimeStore

STREAMS = ("stdout", "stderr")
_BAD_UTF8 = re.compile("[\udc80-\udcff]")


@dataclass(frozen=True)
class OutputLimits:
    stream_bytes: int = 1_048_576
    run_bytes: int = 25_165_824
    total_bytes: int = 268_435_456
    retention_seconds: float = 604_800


DEFAULT_LIMITS = OutputLimits()


class AcceptanceOutputs:
    def __init__(
        self, store: RuntimeStore, state_dir: Path, *, limits: OutputLimits = DEFAULT_LIMITS,
        clock: Callable[[], float] = time.time,
    ):
        self.store = store
        self.root = state_dir.resolve() / "acceptance-output"
        self.limits = limits
        self.clock = clock
        self.active: set[str] = set()
        self.total_bytes = 0
        self.run_bytes: dict[str, int] = defaultdict(int)
        self.storage_error: int | None = None
        self.records: dict[str, dict[str, Any]] = {}
        self.expired: set[str] = set()
        for event in store.acceptance_output_events():
            payload = event["payload"]
            artifact = payload["artifact_id"]
            if event["type"] == "acceptance.output_expired":
                self.expired.add(artifact)
            elif event["type"] != "acceptance.output_cleanup_failed":
                self.records[artifact] = event
        self._scan_usage()

    @staticmethod
    def _run_key(run_id: str) -> str:
        return hashlib.sha256(run_id.encode()).hexdigest()

    def _safe(self, path: Path) -> Path:
        current = path
        while current != self.root.parent:
            if current.is_symlink():
                raise OSError(errno.ELOOP, "Acceptance output contains a symbolic link")
            current = current.parent
        return path

    def _path(self, run_id: str, artifact: str, stream: str, *, sealed: bool) -> Path:
        # Identities come from canonical facts; no client path is accepted.
        if not re.fullmatch(r"[a-f0-9]{32}", artifact) or stream not in STREAMS:
            raise OSError(errno.EINVAL, "Invalid acceptance output identity")
        suffix = "log" if sealed else "part"
        return self._safe(self.root / self._run_key(run_id) / artifact / f"{stream}.{suffix}")

    def _scan_usage(self) -> None:
        self.total_bytes = 0
        self.run_bytes.clear()
        self.storage_error = None
        try:
            self._safe(self.root)
            if not self.root.exists():
                return
            for run in self.root.iterdir():
                self._safe(run)
                for artifact in run.iterdir():
                    self._safe(artifact)
                    for path in artifact.iterdir():
                        self._safe(path)
                        size = path.stat().st_size
                        self.run_bytes[run.name] += size
                        self.total_bytes += size
        except OSError as exc:
            # Unknown disk usage must not become an apparent empty quota.
            self.storage_error = exc.errno or errno.EIO

    def start(
        self, session_id: str, run_id: str, call_id: str, *, secrets: tuple[str, ...],
        clean: Callable[[str], str],
    ) -> OutputCapture:
        self.cleanup()
        artifact = uuid.uuid4().hex
        event = self.store.append_fact(session_id, "acceptance.output_started", {
            "version": 1, "artifact_id": artifact, "call_id": call_id, "source_run_id": run_id,
        })
        self.records[artifact] = event
        self.active.add(artifact)
        return OutputCapture(self, event, secrets, clean)

    def _read(
        self, path: Path, max_bytes: int, *, offset: int = 0, limit: int = 0,
    ) -> dict[str, Any]:
        self._safe(path)
        flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_NONBLOCK", 0)
        descriptor = os.open(path, flags)
        with os.fdopen(descriptor, "rb") as source:
            info = os.fstat(source.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_size > max_bytes:
                raise OSError(errno.EINVAL, "Invalid acceptance output file")
            decoder = codecs.getincrementaldecoder("utf-8")("surrogateescape")
            digest = hashlib.sha256()
            size = characters = 0
            lossy = False
            parts: list[str] = []
            while True:
                raw = source.read(8192)
                digest.update(raw)
                size += len(raw)
                if size > max_bytes:
                    raise OSError(errno.EFBIG, "Acceptance output grew during reading")
                text = decoder.decode(raw, final=not raw)
                lossy = lossy or bool(_BAD_UTF8.search(text))
                text = _BAD_UTF8.sub("\ufffd", text)
                start = max(0, offset - characters)
                end = max(0, min(len(text), offset + limit - characters))
                if end > start:
                    parts.append(text[start:end])
                characters += len(text)
                if not raw:
                    break
        return {"stored_bytes": size, "stored_chars": characters,
                "sha256": digest.hexdigest(), "encoding_loss": lossy, "text": "".join(parts)}

    def _record(self, event: dict[str, Any], streams: dict[str, Any]) -> dict[str, Any]:
        payload = {**event["payload"], "streams": streams}
        record = self.store.append_fact(
            event["session_id"], "acceptance.output_recorded", payload,
        )
        self.records[payload["artifact_id"]] = record
        return payload

    def recover(self) -> None:
        """Only Host startup calls this, after interrupted runs have been recovered."""
        for event in list(self.records.values()):
            if event["type"] != "acceptance.output_started":
                continue
            streams = {}
            for stream in STREAMS:
                value: dict[str, Any] = {
                    "received_bytes": None, "stored_bytes": 0, "stored_chars": 0,
                    "sha256": None, "sealed": False, "encoding_loss": False,
                    "capture_state": "interrupted", "reason": "process_restart",
                }
                # A crash may fall between rename and publishing the final fact.
                for sealed in (True, False):
                    try:
                        path = self._path(
                            event["payload"]["source_run_id"],
                            event["payload"]["artifact_id"], stream,
                            sealed=sealed,
                        )
                        snapshot = self._read(path, self.limits.stream_bytes)
                    except FileNotFoundError:
                        continue
                    except OSError as exc:
                        value["storage_errno"] = exc.errno
                        break
                    snapshot.pop("text")
                    value.update(snapshot, sealed=sealed)
                    break
                streams[stream] = value
            self._record(event, streams)
        self.cleanup()

    def _expires(self, event: dict[str, Any]) -> bool:
        terminal = self.store.run_terminal_at(event["payload"]["source_run_id"])
        return terminal is not None and self.clock() - terminal >= self.limits.retention_seconds

    def cleanup(self) -> None:
        for artifact, event in list(self.records.items()):
            if artifact in self.active or not self._expires(event):
                continue
            if artifact not in self.expired:
                self.store.append_fact(event["session_id"], "acceptance.output_expired", {
                    "artifact_id": artifact, "call_id": event["payload"]["call_id"],
                    "source_run_id": event["payload"]["source_run_id"],
                })
                self.expired.add(artifact)
            try:
                directory = self._path(
                    event["payload"]["source_run_id"], artifact, "stdout", sealed=False,
                ).parent
                if directory.exists():
                    for path in directory.iterdir():
                        self._safe(path).unlink()
                    directory.rmdir()
                    if not any(directory.parent.iterdir()):
                        directory.parent.rmdir()
            except OSError as exc:
                self.store.append_fact(event["session_id"], "acceptance.output_cleanup_failed", {
                    "artifact_id": artifact, "call_id": event["payload"]["call_id"],
                    "source_run_id": event["payload"]["source_run_id"],
                    "storage_errno": exc.errno,
                })
        self._scan_usage()

    def page(
        self, run_id: str, evidence: dict[str, Any], stream: str, offset: int, limit: int,
    ) -> str:
        artifact = evidence["artifact_id"]
        event = self.records.get(artifact)
        if artifact in self.expired or (event is not None and self._expires(event)):
            return "Error: acceptance output unavailable; availability=expired"
        value = evidence["streams"][stream]
        if value["sha256"] is None:
            return (
                "Error: acceptance output unavailable; availability=not_saved; "
                f"capture_state={value['capture_state']}; reason={value['reason']}"
            )
        try:
            path = self._path(run_id, artifact, stream, sealed=value["sealed"])
            found = self._read(path, value["stored_bytes"], offset=offset, limit=limit)
        except FileNotFoundError:
            return "Error: acceptance output unavailable; availability=missing"
        except OSError:
            return "Error: acceptance output unavailable; availability=corrupt_or_unreadable"
        if found["sha256"] != value["sha256"] or found["stored_chars"] != value["stored_chars"]:
            return "Error: acceptance output unavailable; availability=corrupt"
        total = found["stored_chars"]
        start, end = min(offset, total), min(offset + limit, total)
        next_hint = f"next_offset={end}" if end < total else "end_of_stream"
        header = (
            f"[Acceptance output stream={stream}; offset_unit=characters; {start}:{end} "
            f"of {total}; {next_hint}; availability=available; "
            f"capture_state={value['capture_state']}; reason={value['reason']}; "
            f"encoding_loss={value['encoding_loss']}]\n"
        )
        return header + found["text"]


class _Stream:
    def __init__(
        self, capture: OutputCapture, name: str, secrets: tuple[str, ...],
        clean: Callable[[str], str],
    ):
        self.capture, self.name = capture, name
        self.decoder = codecs.getincrementaldecoder("utf-8")("surrogateescape")
        self.redactor = SafeTextBuffer(secrets, clean)
        self.received_bytes = self.stored_bytes = 0
        self.state = "collecting"
        self.reason: str | None = None
        self.encoding_loss = False
        self.file: BinaryIO | None = None
        self.path: Path | None = None
        try:
            owner = capture.owner
            if owner.storage_error is not None:
                raise OSError(owner.storage_error, "Acceptance output storage unavailable")
            self.path = owner._path(capture.run_id, capture.artifact, name, sealed=False)
            self.path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
            descriptor = os.open(self.path, os.O_WRONLY | os.O_CREAT | os.O_EXCL
                                 | getattr(os, "O_NOFOLLOW", 0), 0o600)
            self.file = os.fdopen(descriptor, "wb", buffering=0)
        except OSError:
            self.state, self.reason = "write_failed", "open_failed"
        if not self.redactor.enabled:
            self.state, self.reason = "redaction_unavailable", "secret_lookahead_limit"

    def feed(self, data: bytes, *, final: bool = False) -> None:
        self.received_bytes += len(data)
        if self.state != "collecting":
            return
        text = self.decoder.decode(data, final=final)
        self.encoding_loss = self.encoding_loss or bool(_BAD_UTF8.search(text))
        safe = self.redactor.feed(_BAD_UTF8.sub("\ufffd", text), final=final).encode("utf-8")
        owner = self.capture.owner
        choices = {
            "stream_quota": owner.limits.stream_bytes - self.stored_bytes,
            "run_quota": owner.limits.run_bytes - owner.run_bytes[self.capture.run_key],
            "global_quota": owner.limits.total_bytes - owner.total_bytes,
        }
        reason = min(choices, key=lambda key: choices[key])
        available = max(0, choices[reason])
        if len(safe) > available:
            safe = safe[:available].decode("utf-8", errors="ignore").encode("utf-8")
            self.state, self.reason = "quota_exceeded", reason
        if not safe:
            return
        assert self.file is not None
        before = self.stored_bytes
        try:
            position = 0
            while position < len(safe):
                written = self.file.write(safe[position:])
                if not written:
                    raise OSError(errno.EIO, "Acceptance output write made no progress")
                position += written
        except OSError:
            self.state, self.reason = "write_failed", "write_failed"
        # These synchronous, bounded writes have no await between quota check
        # and settlement; all observers execute on the one Host event loop.
        try:
            self.stored_bytes = os.fstat(self.file.fileno()).st_size
        except OSError:
            self.state, self.reason = "write_failed", "stat_failed"
            # Keep the attempted space reserved until a filesystem rescan.
            self.stored_bytes = before + len(safe)
        delta = self.stored_bytes - before
        owner.run_bytes[self.capture.run_key] += delta
        owner.total_bytes += delta

    def finish(self, outcome: str) -> dict[str, Any]:
        self.feed(b"", final=True)
        if self.state == "collecting":
            self.state = (outcome if outcome in ("complete", "not_started") else "interrupted")
            self.reason = None if outcome == "complete" else outcome
        sealed = False
        if self.file is not None:
            try:
                os.fsync(self.file.fileno())
            except OSError:
                self.state, self.reason = "write_failed", "sync_failed"
            finally:
                try:
                    self.file.close()
                except OSError:
                    self.state, self.reason = "write_failed", "close_failed"
            if self.state == "complete":
                assert self.path is not None
                try:
                    destination = self.capture.owner._path(
                        self.capture.run_id, self.capture.artifact, self.name, sealed=True,
                    )
                    self.path.replace(destination)
                    sealed, self.path = True, destination
                    if os.name != "nt":
                        directory = os.open(destination.parent, os.O_RDONLY)
                        try:
                            os.fsync(directory)
                        finally:
                            os.close(directory)
                except OSError:
                    self.state, self.reason = "write_failed", "finalize_failed"
        value: dict[str, Any] = {
            "received_bytes": self.received_bytes, "stored_bytes": 0, "stored_chars": 0,
            "sha256": None, "sealed": sealed, "encoding_loss": self.encoding_loss,
            "capture_state": self.state, "reason": self.reason,
        }
        if self.path is not None and self.file is not None:
            try:
                snapshot = self.capture.owner._read(
                    self.path, self.capture.owner.limits.stream_bytes,
                )
            except OSError:
                value.update(capture_state="write_failed", reason="snapshot_failed")
            else:
                snapshot.pop("text")
                snapshot["encoding_loss"] |= self.encoding_loss
                value.update(snapshot)
        return value


class OutputCapture:
    def __init__(
        self, owner: AcceptanceOutputs, event: dict[str, Any], secrets: tuple[str, ...],
        clean: Callable[[str], str],
    ):
        self.owner, self.event = owner, event
        self.run_id = event["payload"]["source_run_id"]
        self.run_key = owner._run_key(self.run_id)
        self.artifact = event["payload"]["artifact_id"]
        self.streams = {name: _Stream(self, name, secrets, clean) for name in STREAMS}

    def feed(self, stream: str, data: bytes) -> None:
        self.streams[stream].feed(data)

    def finish(self, outcome: str) -> dict[str, Any]:
        try:
            streams = {name: stream.finish(outcome) for name, stream in self.streams.items()}
            return self.owner._record(self.event, streams)
        finally:
            self.owner.active.discard(self.artifact)

documents.eventide/attachments.py:
"""Session-scoped attachment storage and provider-neutral prompt composition."""

from __future__ import annotations

import base64
import hashlib
import json
import mimetypes
import os
import re
import tempfile
import time
import uuid
from pathlib import Path
from typing import Any

from eventide.config import normalize_provider

MAX_UPLOAD_BYTES = 10 * 1024 * 1024
MAX_INLINE_BYTES = 512 * 1024

_ATTACHMENT_ID = re.compile(r"^att_[0-9a-f]{12}$")
_SAFE_COMPONENT = re.compile(r"[^A-Za-z0-9._-]")
_MEDIA_TYPE = re.compile(r"^[A-Za-z0-9!#$&^_.+-]+/[A-Za-z0-9!#$&^_.+-]+$")
_WINDOWS_RESERVED = re.compile(r"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$", re.IGNORECASE)
_TEXT_MEDIA_TYPES = {
    "application/json",
    "application/ld+json",
    "application/javascript",
    "application/xml",
    "application/yaml",
    "application/x-yaml",
}


def new_attachment_id() -> str:
    return f"att_{uuid.uuid4().hex[:12]}"


def _safe_session_dir(session_id: str) -> str:
    if not isinstance(session_id, str) or not session_id:
        raise ValueError("会话 id 无效")
    return "~" + hashlib.sha256(session_id.encode("utf-8")).hexdigest()


def _legacy_session_dir(session_id: str) -> str | None:
    """Only unchanged portable names can identify a legacy session directory."""
    if (
        _SAFE_COMPONENT.search(session_id)
        or session_id in {".", ".."}
        or session_id.endswith(".")
        or _WINDOWS_RESERVED.fullmatch(session_id.split(".", 1)[0])
        or len(session_id) > 128
    ):
        return None
    return session_id


def _check_path(path: Path, state_dir: Path, *, directory: bool = False) -> None:
    if path.is_symlink():
        raise ValueError("附件路径不能使用符号链接")
    if not path.resolve().is_relative_to(state_dir.resolve()):
        raise ValueError("附件路径越出状态目录")
    if not path.exists():
        return
    # On case-insensitive filesystems, an old ownerless A/ directory must not
    # also be accepted as a/. New hashed names do not have this ambiguity.
    if not any(entry.name == path.name for entry in path.parent.iterdir()):
        raise ValueError("附件路径大小写不一致，无法确认会话归属")
    if directory and not path.is_dir():
        raise ValueError("附件目录无效")
    if not directory and not path.is_file():
        raise ValueError("附件文件无效")


def _primary_root(state_dir: str | Path, session_id: str) -> Path:
    state = Path(state_dir)
    root = state / "attachments"
    _check_path(root, state, directory=True)
    primary = root / _safe_session_dir(session_id)
    _check_path(primary, state, directory=True)
    return primary


def _session_roots(state_dir: str | Path, session_id: str) -> list[Path]:
    state = Path(state_dir)
    primary = _primary_root(state_dir, session_id)
    roots = [primary]
    legacy = _legacy_session_dir(session_id)
    if legacy is not None:
        legacy_root = primary.parent / legacy
        if legacy_root.exists() and not any(
            entry.name == legacy for entry in primary.parent.iterdir()
        ):
            # A casing alias is another legacy directory, never a fallback.
            return roots
        _check_path(legacy_root, state, directory=True)
        roots.append(legacy_root)
    return roots


def _atomic_write(path: Path, meta: dict[str, Any], *, replace: bool) -> None:
    """Publish complete JSON; initial saves never overwrite an existing id."""
    temporary: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w", encoding="utf-8", dir=path.parent, prefix=".attachment-", delete=False
        ) as handle:
            temporary = Path(handle.name)
            json.dump(meta, handle, ensure_ascii=False)
            handle.flush()
            os.fsync(handle.fileno())
        if replace:
            os.replace(temporary, path)
        else:
            try:
                os.link(temporary, path)
            except FileExistsError as exc:
                raise ValueError(f"附件 id 已存在：{path.name}") from exc
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def _decode_base64(content_base64: str | None) -> bytes:
    if content_base64 is None:
        content_base64 = ""
    if not isinstance(content_base64, str):
        raise ValueError("附件内容不是有效的 base64")
    if len(content_base64) > 4 * ((MAX_UPLOAD_BYTES + 2) // 3):
        raise ValueError(f"附件超过 {MAX_UPLOAD_BYTES // (1024 * 1024)}MB 上限")
    try:
        raw = base64.b64decode(content_base64, validate=True)
    except Exception as exc:
        raise ValueError("附件内容不是有效的 base64") from exc
    if len(raw) > MAX_UPLOAD_BYTES:
        raise ValueError(f"附件超过 {MAX_UPLOAD_BYTES // (1024 * 1024)}MB 上限")
    return raw


def _normalized_media_type(name: str, media_type: str | None) -> str:
    value = (media_type or mimetypes.guess_type(name)[0] or "application/octet-stream").strip()
    value = value.split(";", 1)[0].strip().lower()
    if not _MEDIA_TYPE.fullmatch(value):
        raise ValueError("附件 media_type 无效")
    return value


def _kind(media_type: str, raw: bytes, *, guess_text: bool = False) -> tuple[str, str | None]:
    if media_type.startswith("image/"):
        return "image", None
    if media_type == "application/pdf":
        return "document", None
    if media_type.startswith("text/") or media_type in _TEXT_MEDIA_TYPES:
        try:
            return "text", raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("文本附件必须使用 UTF-8 编码") from exc
    if guess_text:
        try:
            return "text", raw.decode("utf-8")
        except UnicodeDecodeError:
            pass
    return "file", None


def decode_attachment(name: str, content_base64: str) -> str:
    """Backwards-compatible UTF-8 decoder used by callers and tests."""
    if not isinstance(name, str) or not name.strip():
        raise ValueError("附件缺少名称")
    raw = _decode_base64(content_base64)
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError("暂仅支持 UTF-8 文本附件") from exc


def attachment_path(state_dir: str | Path, session_id: str, attachment_id: str) -> Path:
    if not isinstance(attachment_id, str) or not _ATTACHMENT_ID.fullmatch(attachment_id):
        raise ValueError(f"非法附件 id：{attachment_id!r}")
    path = _primary_root(state_dir, session_id) / attachment_id
    _check_path(path, Path(state_dir))
    return path


def validate_upload(name: str, content_base64: str, media_type: str | None = None) -> None:
    """Validate request data before recording a potentially effectful upload."""
    if not isinstance(name, str) or not name.strip():
        raise ValueError("附件缺少名称")
    _decode_base64(content_base64)
    _normalized_media_type(name, media_type)


def save_attachment(
    state_dir: str | Path,
    session_id: str,
    attachment_id: str,
    name: str,
    content_base64: str,
    media_type: str | None = None,
) -> dict[str, Any]:
    if not isinstance(name, str) or not name.strip():
        raise ValueError("附件缺少名称")
    raw = _decode_base64(content_base64)
    normalized_type = _normalized_media_type(name, media_type)
    kind, text = _kind(normalized_type, raw, guess_text=media_type is None)
    if kind == "text" and normalized_type == "application/octet-stream":
        normalized_type = "text/plain"
    path = attachment_path(state_dir, session_id, attachment_id)
    for root in _session_roots(state_dir, session_id):
        existing = root / attachment_id
        _check_path(existing, Path(state_dir))
        if existing.exists():
            raise ValueError(f"附件 id 已存在：{attachment_id}")
    path.parent.mkdir(parents=True, exist_ok=True)
    path = attachment_path(state_dir, session_id, attachment_id)
    meta: dict[str, Any] = {
        "version": 3,
        "session_id": session_id,
        "name": name,
        "size": len(raw),
        "media_type": normalized_type,
        "kind": kind,
        "created_at": time.time(),
        "used": False,
    }
    if text is not None:
        meta["text"] = text
    else:
        meta["content_base64"] = base64.b64encode(raw).decode("ascii")
    _atomic_write(path, meta, replace=False)
    return _public_metadata(attachment_id, meta)


def _read_meta(
    path: Path, attachment_id: str, session_id: str, *, legacy: bool = False
) -> dict[str, Any]:
    if not path.is_file():
        raise ValueError(f"附件不存在：{attachment_id}")
    try:
        meta = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError(f"附件数据损坏：{attachment_id}") from exc
    if not isinstance(meta, dict) or not isinstance(meta.get("name"), str):
        raise ValueError(f"附件数据损坏：{attachment_id}")
    if "session_id" in meta:
        if meta["session_id"] != session_id:
            raise ValueError(f"附件不属于当前会话：{attachment_id}")
    elif (
        not legacy
        or session_id != session_id.lower()
        or meta.get("version") not in (None, 1, 2)
    ):
        raise ValueError(f"附件缺少可确认的会话归属：{attachment_id}")
    if "version" not in meta and isinstance(meta.get("text"), str):
        meta = {
            **meta,
            "version": 1,
            "size": len(meta["text"].encode("utf-8")),
            "media_type": mimetypes.guess_type(meta["name"])[0] or "text/plain",
            "kind": "text",
            "created_at": path.stat().st_mtime,
            "used": bool(meta.get("used", False)),
        }
    required = ("size", "media_type", "kind", "created_at", "used")
    if any(key not in meta for key in required):
        raise ValueError(f"附件数据损坏：{attachment_id}")
    if meta["kind"] == "text" and not isinstance(meta.get("text"), str):
        raise ValueError(f"附件数据损坏：{attachment_id}")
    if meta["kind"] != "text" and not isinstance(meta.get("content_base64"), str):
        raise ValueError(f"附件数据损坏：{attachment_id}")
    return meta


def _load_meta(
    state_dir: str | Path, session_id: str, attachment_id: str
) -> tuple[Path, dict[str, Any]]:
    # Validate the public id even if neither directory exists.
    attachment_path(state_dir, session_id, attachment_id)
    found: tuple[Path, dict[str, Any]] | None = None
    for index, root in enumerate(_session_roots(state_dir, session_id)):
        path = root / attachment_id
        _check_path(path, Path(state_dir))
        if not path.exists():
            continue
        meta = _read_meta(path, attachment_id, session_id, legacy=index != 0)
        if found is not None:
            raise ValueError(f"附件 id 重复：{attachment_id}")
        found = path, meta
    if found is None:
        raise ValueError(f"附件不存在：{attachment_id}")
    return found


def _public_metadata(attachment_id: str, meta: dict[str, Any]) -> dict[str, Any]:
    return {
        "attachment_id": attachment_id,
        "name": meta["name"],
        "size": int(meta["size"]),
        "media_type": str(meta["media_type"]),
        "kind": str(meta["kind"]),
        "created_at": float(meta["created_at"]),
        "used": bool(meta["used"]),
    }


def load_attachment(state_dir: str | Path, session_id: str, attachment_id: str) -> dict[str, Any]:
    _, meta = _load_meta(state_dir, session_id, attachment_id)
    record = _public_metadata(attachment_id, meta)
    if meta["kind"] == "text":
        record["content"] = meta["text"]
    else:
        record["data"] = meta["content_base64"]
    return record


def load_attachments(
    state_dir: str | Path, session_id: str, attachment_ids: list[str]
) -> list[dict[str, Any]]:
    return [load_attachment(state_dir, session_id, item) for item in (attachment_ids or [])]


def list_attachments(
    state_dir: str | Path, session_id: str, *, include_used: bool = False
) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    seen: set[str] = set()
    for index, root in enumerate(_session_roots(state_dir, session_id)):
        if not root.is_dir():
            continue
        for path in root.iterdir():
            if not _ATTACHMENT_ID.fullmatch(path.name):
                continue
            _check_path(path, Path(state_dir))
            meta = _read_meta(path, path.name, session_id, legacy=index != 0)
            if path.name in seen:
                raise ValueError(f"附件 id 重复：{path.name}")
            seen.add(path.name)
            if include_used or not meta["used"]:
                records.append(_public_metadata(path.name, meta))
    return sorted(records, key=lambda item: (item["created_at"], item["attachment_id"]))


def mark_attachments_used(
    state_dir: str | Path, session_id: str, attachment_ids: list[str]
) -> None:
    # A bad/foreign id anywhere in the request must leave every valid chip
    # untouched. Filesystem failure during publication is not a DB transaction.
    validated = dict(_load_meta(state_dir, session_id, item) for item in attachment_ids)
    for path, meta in validated.items():
        if meta["used"]:
            continue
        meta["used"] = True
        meta["version"] = 3
        meta["session_id"] = session_id
        _check_path(path, Path(state_dir))
        _atomic_write(path, meta, replace=True)


def delete_attachment(state_dir: str | Path, session_id: str, attachment_id: str) -> dict[str, Any]:
    path, meta = _load_meta(state_dir, session_id, attachment_id)
    if meta["used"]:
        raise ValueError("附件已用于工作记录，不能删除")
    path.unlink()
    return _public_metadata(attachment_id, meta)


def attachment_bytes(record: dict[str, Any]) -> bytes:
    if record["kind"] == "text":
        return str(record.get("content", "")).encode("utf-8")
    return _decode_base64(str(record.get("data", "")))


def validate_for_provider(records: list[dict[str, Any]], provider: str) -> None:
    normalized = normalize_provider(provider)
    for record in records:
        kind = record["kind"]
        if kind in {"text", "image"}:
            continue
        if kind == "document" and normalized in {"anthropic", "openai_responses", "scripted"}:
            continue
        raise ValueError(
            f"当前 Provider（{normalized}）不能把附件 {record['name']} 发送给模型；"
            "可先转换为 UTF-8 文本或图片"
        )


def compose_prompt(prompt: str, records: list[dict[str, Any]]) -> str:
    """Inline text attachments into a prompt; retained for backwards compatibility."""
    parts = [prompt or ""]
    for record in records or []:
        if record.get("kind", "text") != "text":
            continue
        text = record.get("content") or ""
        encoded = text.encode("utf-8")
        marker = ""
        if len(encoded) > MAX_INLINE_BYTES:
            text = encoded[:MAX_INLINE_BYTES].decode("utf-8", "ignore")
            marker = "\n[附件内容过长，已截断]"
        parts.append(f"\n\n--- 附件：{record.get('name') or '未命名'} ---\n{text}{marker}")
    return "".join(parts)


def compose_message(prompt: str, records: list[dict[str, Any]]) -> dict[str, Any]:
    text = compose_prompt(prompt, records)
    binary = [record for record in records if record.get("kind") != "text"]
    if not binary:
        return {"role": "user", "content": text}
    blocks: list[dict[str, Any]] = [{"type": "text", "text": text}]
    blocks.extend(
        {
            "type": "attachment",
            "attachment_id": record["attachment_id"],
            "name": record["name"],
            "media_type": record["media_type"],
            "kind": record["kind"],
            "size": record["size"],
        }
        for record in binary
    )
    return {"role": "user", "content": blocks}


def hydrate_messages(
    state_dir: str | Path, session_id: str, messages: list[dict[str, Any]]
) -> list[dict[str, Any]]:
    hydrated: list[dict[str, Any]] = []
    for message in messages:
        content = message.get("content")
        if not isinstance(content, list):
            hydrated.append(message)
            continue
        blocks: list[Any] = []
        for block in content:
            if not isinstance(block, dict) or block.get("type") != "attachment":
                blocks.append(block)
                continue
            record = load_attachment(state_dir, session_id, str(block.get("attachment_id", "")))
            blocks.append(
                {
                    "type": "image" if record["kind"] == "image" else "file",
                    "name": record["name"],
                    "media_type": record["media_type"],
                    "data": record["data"],
                }
            )
        hydrated.append({**message, "content": blocks})
    return hydrated

